class Solution:
    def maxLength(self, arr: list[str]) -> int:
        masks = []
        for s in arr:
            mask = 0
            valid = True
            for c in s:
                bit = 1 << (ord(c) - ord('a'))
                if mask & bit:
                    valid = False
                    break
                mask |= bit
            if valid:
                masks.append((mask, len(s)))
        self.ans = 0
        def bt(i, cur_mask, cur_len):
            self.ans = max(self.ans, cur_len)
            for j in range(i, len(masks)):
                m, l = masks[j]
                if cur_mask & m == 0:
                    bt(j + 1, cur_mask | m, cur_len + l)
        bt(0, 0, 0)
        return self.ans

